import {
    Table,
    ReferenceColumn,
    ListColumn,
    TemplateValueColumn,
    GenericColumn,
    IntegerColumn,
    ChoiceColumn,
    StringColumn,
    BooleanColumn,
    FieldNameColumn,
    GuidColumn,
    DomainIdColumn,
    TranslatedTextColumn,
    ConditionsColumn,
    UserRolesColumn,
    DomainPathColumn,
    TableNameColumn,
    ScriptColumn,
    JsonColumn,
} from '../../db'

export const sys_declarative_action_assignment = Table({
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        no_text_index: true,
        update_synch: true,
    },
    display: 'label',
    extends: 'sys_metadata',
    label: 'Action Assignment',
    name: 'sys_declarative_action_assignment',
    schema: {
        sys_overrides: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Script being overridden by the current record',
                    label: 'Overrides',
                    plural: 'Overrides',
                },
            ],
            referenceTable: 'sys_declarative_action_assignment',
        }),
        client_conditions_on_fields: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            dependent: 'model',
            label: 'Client Conditions on Fields',
            maxLength: 1024,
            referenceTable: 'sys_declarative_action_model_field',
        }),
        payload_map: TemplateValueColumn({
            dependent: 'client_action.payload_field_table',
            label: [
                {
                    hint: 'Set values to the listed properties',
                    label: 'Payload Map',
                    plural: 'Payload Maps',
                },
            ],
            maxLength: 8000,
        }),
        order: GenericColumn({
            columnType: 'order_index',
            default: '0',
            label: 'Order',
        }),
        specificity: IntegerColumn({
            label: 'Specificity',
            readOnly: true,
            readOnlyOption: 'strict_read_only',
        }),
        declarative_action_type: ChoiceColumn({
            default: 'server_script',
            choices: {
                action_component: {
                    label: 'UI Component',
                    sequence: 1,
                },
                dispatch_action: {
                    label: 'Client Action',
                    sequence: 2,
                },
                server_script: {
                    label: 'Server Script',
                    sequence: 3,
                },
                uxf_client_action: {
                    label: 'UXF Client Action',
                    sequence: 4,
                },
                client_script: {
                    label: 'Client Script',
                    sequence: 5,
                },
                interaction: {
                    label: 'UI interaction',
                    sequence: 5,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Implemented as',
        }),
        required_translations: GenericColumn({
            columnType: 'json_translations',
            label: [
                {
                    hint: 'JSON Array, holding the translations required by this declarative action assignment',
                    label: 'Required translations',
                    plural: 'Required translations',
                },
            ],
            maxLength: 8000,
        }),
        icon: StringColumn({
            label: 'Icon',
        }),
        group_by: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Whether or not the action is grouped in any group',
                    label: 'Group By',
                    plural: 'Group Bys',
                },
            ],
        }),
        required_roles: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: [
                {
                    hint: 'Recommend do not use. This field uses role sys IDs to determine access. If "Required user role names" field is populated, this field does not take effect.',
                    label: 'Required Roles',
                    plural: 'Required Roles',
                },
            ],
            maxLength: 1024,
            referenceTable: 'sys_user_role',
        }),
        scripted_client_condition: GenericColumn({
            columnType: 'condition_string',
            label: [
                {
                    hint: 'Define scripted condition to dynamically display the action',
                    label: 'Scripted Client Condition',
                    plural: 'Scripted Client Conditions',
                },
            ],
            maxLength: 254,
        }),
        client_action: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: 'Specify client action',
            mandatory: true,
            referenceTable: 'sys_declarative_action_payload_definition',
            referenceQual: "javascript: 'applicable_to=' + current.model",
        }),
        field_name: FieldNameColumn({
            attributes: {
                allow_null: true,
                allow_references: true,
            },
            dependent: 'table',
            label: 'Field Name',
        }),
        read_access: BooleanColumn({
            label: [
                {
                    hint: 'Action is only applicable when the user has a read access',
                    label: 'Requires read access',
                    plural: 'Requires read access',
                },
            ],
        }),
        button_position: ChoiceColumn({
            default: 'right',
            choices: {
                right: {
                    label: 'Right',
                    sequence: 1,
                },
                left: {
                    label: 'Left',
                    sequence: 2,
                },
            },
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Use Button Position to place the action button on the left or right side of the activity',
                    label: 'Button Position',
                    plural: 'Button Positions',
                },
            ],
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                },
            ],
            primary: true,
        }),
        animate_icon: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'If true, the icon will be animated. Not all components and icons support animation.',
                    label: 'Animate icon',
                    plural: 'Animate icons',
                },
            ],
        }),
        action: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Action',
            referenceTable: 'sys_declarative_action_definition',
        }),
        action_payload: StringColumn({
            label: 'Action Payload',
            maxLength: 65535,
        }),
        write_access: BooleanColumn({
            label: [
                {
                    hint: 'Action is only applicable when the user has a write access',
                    label: 'Requires write access',
                    plural: 'Requires write access',
                },
            ],
        }),
        declarative_action_render_mode: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                ref_auto_completer: 'AJAXReferenceChoice',
            },
            dropdown: 'dropdown_without_none',
            label: 'Render Mode',
            referenceTable: 'sys_declarative_action_render_mode',
            referenceQual: "javascript:'applicable_toLIKE'+current.model",
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the action belongs',
                    label: 'Domain',
                    plural: 'Domains',
                },
            ],
            readOnly: true,
            readOnlyOption: 'strict_read_only',
        }),
        description: StringColumn({
            label: 'Description',
            maxLength: 4000,
        }),
        confirmation_message: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: [
                {
                    hint: 'Message to display when prompting user for confirmation',
                    label: 'Confirmation Message',
                    plural: 'Confirmation Messages',
                },
            ],
            maxLength: 4000,
        }),
        view: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'View',
            referenceTable: 'sys_ui_view',
        }),
        dependency: StringColumn({
            label: 'Dependency',
            maxLength: 255,
        }),
        record_selection_required: BooleanColumn({
            label: [
                {
                    hint: 'By enabling this at least one list item must be selected in order perform the action',
                    label: 'Record Selection Required',
                    plural: 'Record Selection Required',
                },
            ],
        }),
        dynamic_record_condition: ConditionsColumn({
            attributes: {
                use_variables: false,
            },
            dependent: 'table',
            label: [
                {
                    hint: 'Evaluated when the selected list items change',
                    label: 'Dynamic Record Conditions',
                    plural: 'Dynamic Record Conditions',
                },
            ],
        }),
        action_name: StringColumn({
            label: 'Action name',
        }),
        model_field_required: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            dependent: 'model',
            label: [
                {
                    hint: 'Selected fields will be resolved to current payload value and pass to action component as props',
                    label: 'Model Fields required',
                    plural: 'Model Fields required',
                },
            ],
            maxLength: 1024,
            referenceTable: 'sys_declarative_action_model_field',
        }),
        required_user_role_names: UserRolesColumn({
            attributes: {
                record_watcher_blacklist: true,
            },
            label: 'Required user role names',
        }),
        enable_for_all_experiences: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Make this action visible in all Configurable Experiences',
                    label: 'Enable for all Configurable Experiences',
                    plural: 'Enable for all Configurable Experiences',
                },
            ],
        }),
        workspace: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Restrict action to a legacy Agent Workspace experience.',
                    help: 'Restrict action to a legacy Agent Workspace experience.',
                    label: 'Workspace',
                    plural: 'Workspaces',
                },
            ],
            referenceTable: 'sys_aw_master_config',
            referenceQual:
                "javascript:(current.action && current.action.workspace) ? 'sys_id=' + current.action.workspace : ''",
        }),
        ui_component: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Select seismic component to render',
                    label: 'Specify UI component',
                    plural: 'Specify UI components',
                },
            ],
            referenceTable: 'sys_ux_lib_component',
            referenceQual: 'deprecated=false^ORdeprecatedISEMPTY',
            useReferenceQualifier: 'simple',
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        label: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Action label',
            mandatory: true,
        }),
        action_type: ChoiceColumn({
            default: 'type',
            choices: {
                type: {
                    label: 'Field type',
                    sequence: 1,
                },
                field: {
                    label: 'Specific field',
                    sequence: 2,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Decorator applies to',
        }),
        create_access: BooleanColumn({
            label: [
                {
                    hint: 'Action is only applicable when the user has a create access',
                    label: 'Requires create access',
                    plural: 'Requires create access',
                },
            ],
        }),
        client_script: GenericColumn({
            columnType: 'script_plain',
            default: 'function onClick() { }',
            label: 'Client Script',
            maxLength: 8000,
        }),
        form_position: StringColumn({
            choices: {
                related_item: {
                    label: 'Related Item',
                    sequence: 1,
                },
                contexual_sidebar: {
                    label: 'Contextual Side Bar',
                    sequence: 2,
                },
                action_bar: {
                    label: 'Action Bar',
                    sequence: 3,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Form position',
        }),
        client_conditions: GenericColumn({
            attributes: {
                key_readonly: true,
                no_actions: true,
            },
            columnType: 'simple_name_values',
            label: [
                {
                    hint: 'Conditions required to render action. The model must meet all the values set.',
                    label: 'Client Conditions',
                    plural: 'Client Conditions',
                },
            ],
            maxLength: 4000,
        }),
        model_conditions: ConditionsColumn({
            dependent: 'model.model_field_table',
            label: [
                {
                    hint: 'Apply conditions to dynamically display the action',
                    label: 'Client Conditions',
                    plural: 'Client Conditions',
                },
            ],
            maxLength: 8000,
        }),
        enabled: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Disabling this will prevent this action from rendering. The system will not fallback to the parent',
                    label: 'Enabled',
                    plural: 'Enabled',
                },
            ],
        }),
        record_conditions: ConditionsColumn({
            dependent: 'table',
            label: [
                {
                    hint: 'Query condition used to enable policy run',
                    label: 'Record Conditions',
                    plural: 'Record Conditions',
                },
            ],
            maxLength: 1000,
        }),
        confirmation_required: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Ask for confirmation before running the server scripts',
                    label: 'Confirmation Required',
                    plural: 'Confirmation Required',
                },
            ],
        }),
        tooltip: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Tooltip',
            maxLength: 255,
        }),
        requires_value: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Action is only applicable when field has value',
                    label: 'Requires Value',
                    plural: 'Requires Values',
                },
            ],
        }),
        button_type: ChoiceColumn({
            default: 'primary',
            choices: {
                primary: {
                    label: 'Primary',
                    sequence: 1,
                },
                secondary: {
                    label: 'Secondary',
                    sequence: 2,
                },
                tertiary: {
                    label: 'Tertiary',
                    sequence: 3,
                },
                'primary-positive': {
                    label: 'Primary Positive',
                    sequence: 4,
                },
                'primary-negative': {
                    label: 'Primary Negative',
                    sequence: 5,
                },
                'secondary-positive': {
                    label: 'Secondary Positive',
                    sequence: 6,
                },
                'secondary-negative': {
                    label: 'Secondary Negative',
                    sequence: 7,
                },
                'primary-ai': {
                    label: 'AI Primary',
                    sequence: 8,
                },
                'secondary-ai': {
                    label: 'AI Secondary',
                    sequence: 9,
                },
                'tertiary-ai': {
                    label: 'AI Tertiary',
                    sequence: 10,
                },
            },
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'Use Button Type to apply visual weights to the action button',
                    label: 'Button type',
                    plural: 'Button types',
                },
            ],
        }),
        dynamic_script_condition: GenericColumn({
            columnType: 'condition_string',
            label: [
                {
                    hint: 'Evaluated when the selected list items change',
                    label: 'Dynamic Script Condition',
                    plural: 'Dynamic Script Conditions',
                },
            ],
            maxLength: 254,
        }),
        design_icon: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Icon',
            referenceTable: 'st_sys_design_system_icon',
        }),
        table: TableNameColumn({
            attributes: {
                base_start: true,
            },
            default: 'global',
            label: 'Table',
            mandatory: true,
        }),
        group: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Group',
            referenceTable: 'sys_declarative_action_group',
        }),
        server_script: ScriptColumn({
            dependent: 'table',
            label: 'Server Script',
        }),
        enable_dynamic_evaluation: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'To enable this feature set Experience Restricted and Record Selection Required as true. When enabled, users are unable to perform an action until all of the selected list items meet the defined conditions',
                    label: 'Enable Dynamic Evaluation',
                    plural: 'Enable Dynamic Evaluations',
                },
            ],
        }),
        interaction: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                field_decorations: 'configure_ui_interaction_input_map',
            },
            label: 'UI interaction',
            referenceTable: 'sys_ui_interaction',
            referenceQual:
                'javascript:new DAModelToUIInteractionRefQual().getApplicableInteractionsRefQual(current.model)',
        }),
        field_type: ChoiceColumn({
            default: 'glide_date',
            choices: {
                domain_id: {
                    label: 'Domain ID',
                },
                glide_list: {
                    label: 'List',
                },
                price: {
                    label: 'Price',
                },
                glide_date: {
                    label: 'Date',
                    sequence: 1,
                },
                glide_date_time: {
                    label: 'Date/Time',
                    sequence: 2,
                },
                decimal: {
                    label: 'Decimal',
                    sequence: 3,
                },
                document_id: {
                    label: 'Document ID',
                    sequence: 4,
                },
                email: {
                    label: 'Email',
                    sequence: 5,
                },
                float: {
                    label: 'Floating point number',
                    sequence: 6,
                },
                integer: {
                    label: 'Integer',
                    sequence: 7,
                },
                password: {
                    label: 'Password (1-way encrypted)',
                    sequence: 8,
                },
                ph_number: {
                    label: 'Phone Number',
                    sequence: 9,
                },
                phone_number_e164: {
                    label: 'Phone Number (E164)',
                    sequence: 10,
                },
                reference: {
                    label: 'Reference',
                    sequence: 11,
                },
                string: {
                    label: 'String',
                    sequence: 12,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Field type',
        }),
        delete_access: BooleanColumn({
            label: [
                {
                    hint: 'Action is only applicable when the user has a delete access',
                    label: 'Requires delete access',
                    plural: 'Requires delete access',
                },
            ],
        }),
        form_fields_required: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Use form fields required to disable the action when required fields are empty.',
                    label: 'Form Fields Required',
                    plural: 'Form Fields Required',
                },
            ],
        }),
        model: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: 'Action Model',
            mandatory: true,
            referenceTable: 'sys_declarative_action_model_definition',
            referenceQual: "javascript:'sys_idIN' + current.action.applicable_to",
        }),
        action_attributes: GenericColumn({
            attributes: {
                key_readonly: true,
                no_actions: true,
            },
            columnType: 'simple_name_values',
            label: 'Component Attributes',
            maxLength: 4000,
        }),
        interaction_input_map: JsonColumn({
            label: [
                {
                    hint: 'Set values to the listed inputs',
                    label: 'Input Map',
                    plural: 'Input Maps',
                },
            ],
            maxLength: 8000,
        }),
        active: BooleanColumn({
            default: true,
            label: [
                {
                    hint: "Disabling this will make the system fallback to the parent table's assignment if applicable",
                    label: 'Active',
                    plural: 'Active',
                },
            ],
        }),
        script_condition: GenericColumn({
            columnType: 'condition_string',
            label: 'Script Condition',
            maxLength: 254,
        }),
        experience_restricted: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Make this action restricted to experiences as specified in action configuration',
                    label: 'Experience Restricted',
                    plural: 'Experience Restricted',
                },
            ],
        }),
    },
    textIndex: true,
})
